```vue
<script setup lang="ts">
// (1) 声明 props：const props = ______({ count: { type: Number, default: 0 } })

// (2) 声明事件：______<{ (e: 'reset'): void }>()

// (3) 具名双向绑定：对应 title prop 与 update:title 事件
const title = ______('title')
</script>

<template>
  <!-- (4) 上面第 (3) 步对应的父组件用法：<my-comp ______="pageTitle" /> -->
  <div>{{ title }}</div>
