补全下面这段 provide/inject 代码的空缺，使其符合官方推荐的响应式与只读纪律：
```js
// Provider 侧
const KEY = Symbol.for('app.theme');   // 用 Symbol 而非字符串 key，目的是 (1)______
const theme = ref('light');
provide(KEY, {
  // 交给消费者的状态必须是：(2)______(theme)
  state: ______(2)______,
  toggle() { theme.value = theme.value === 'light' ? 'dark' : 'light'; }
});

// Consumer 侧（深埋在组件树里）
// 第三参传 true 的含义是：把第二个参数当作 (3)______ 来处理，只在真的注入不到时才执行
const ctx = inject(KEY, () => ({ state: { value: 'light' }, toggle() {} }), true);

watchEffect(() => {
  // 这里必须写成 ctx.state.______(4)______ 才能建立响应式依赖
  document.documentElement.dataset.theme = ctx.state.value;
});
```
